-- Recorded tracks (aret-backend#4, spec §7.2). Runs as role `tracks`, whose search_path puts the
-- table in schema `tracks`; PostGIS types come from `public`.

CREATE TABLE tracks (
    -- Generated by the client (UUID v7) so uploads can be retried without duplicates
    id           uuid PRIMARY KEY,
    -- Kratos identity id of the owner; no foreign key across services
    owner_id     uuid NOT NULL,
    title        text NOT NULL DEFAULT '' CHECK (char_length(title) <= 200),
    started_at   timestamptz NOT NULL,
    ended_at     timestamptz NOT NULL CHECK (ended_at >= started_at),
    -- Computed by the server
    distance_m   double precision NOT NULL CHECK (distance_m >= 0),
    ascent_m     double precision NOT NULL CHECK (ascent_m >= 0),
    descent_m    double precision NOT NULL CHECK (descent_m >= 0),
    point_count  integer NOT NULL CHECK (point_count >= 2),
    -- Every recorded point: X = longitude, Y = latitude, Z = elevation (m), M = Unix time (s)
    geom         geometry(LineStringZM, 4326) NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- "My tracks, newest first" with cursor pagination
CREATE INDEX tracks_owner_started_idx ON tracks (owner_id, started_at DESC, id DESC);
-- Spatial queries later ("tracks near here")
CREATE INDEX tracks_geom_idx ON tracks USING gist (geom);
